import { ViewTransition } from 'react'

// Maps Link `transitionTypes` to the CSS classes in globals.css. Transitions
// without a type (browser back/forward, refresh, Suspense reveals) don't slide.
const directional = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

// Must wrap page content, not the layout: layouts persist across navigations,
// so enter/exit never fire there.
export function PageTransition({ children }: { children: React.ReactNode }) {
  return (
    <ViewTransition enter={directional} exit={directional} default="none">
      {children}
    </ViewTransition>
  )
}

