import { chromium } from '/home/vercel-sandbox/.npm/_npx/e41f203b7505f1fb/node_modules/playwright-core/index.mjs'

const BASE = 'http://localhost:3123'

// Injected before any page script: wraps startViewTransition so we can record
// the transition types, which elements carried a view-transition-name in the
// old and new DOM, and which CSS animations ran on the ::view-transition pseudos.
const initScript = `
  window.__vt = [];
  const orig = Document.prototype.startViewTransition;
  Document.prototype.startViewTransition = function (arg) {
    const named = () => [...document.querySelectorAll('*')]
      .map(el => [el.className, getComputedStyle(el).viewTransitionName])
      .filter(([, n]) => n && n !== 'none')
      .map(([c, n]) => c + ' => ' + n);
    const rec = { types: [], oldNames: named(), newNames: [], animations: [] };
    window.__vt.push(rec);
    const update = typeof arg === 'function' ? arg : arg?.update;
    rec.types = typeof arg === 'function' ? [] : [...(arg?.types ?? [])];
    const wrapped = async () => {
      const r = await update?.();
      rec.newNames = named();
      return r;
    };
    const vt = orig.call(this, typeof arg === 'function' ? wrapped : { ...arg, update: wrapped });
    vt.ready.then(() => {
      rec.animations = document.getAnimations()
        .filter(a => a.effect?.pseudoElement)
        .map(a => a.effect.pseudoElement + ' : ' + (a.animationName ?? ''));
    }).catch(e => { rec.readyError = String(e); });
    return vt;
  };
`

async function run(reducedMotion) {
  const browser = await chromium.launch()
  const ctx = await browser.newContext({
    reducedMotion: reducedMotion ? 'reduce' : 'no-preference',
    viewport: { width: 1200, height: 800 },
  })
  const page = await ctx.newPage()
  await page.addInitScript(initScript)
  page.on('pageerror', (e) => console.log('PAGE ERROR', e.message))

  await page.goto(BASE + '/')
  await page.waitForSelector('.product-card')
  // let prefetch settle so the detail page commits in the same transition
  await page.waitForTimeout(1500)

  await page.click('a[href="/product/leather-backpack"]')
  await page.waitForSelector('.product-hero')
  await page.waitForSelector('.product-description')
  await page.waitForTimeout(800)

  await page.click('a.back-link')
  await page.waitForSelector('.product-grid')
  await page.waitForTimeout(800)

  const recs = await page.evaluate(() => window.__vt)
  console.log(`\n===== reducedMotion=${reducedMotion} : ${recs.length} startViewTransition call(s) =====`)
  for (const [i, r] of recs.entries()) {
    console.log(`\n-- transition #${i + 1}`)
    console.log('types      :', JSON.stringify(r.types))
    console.log('old names  :', JSON.stringify(r.oldNames))
    console.log('new names  :', JSON.stringify(r.newNames))
    console.log('animations :')
    for (const a of [...new Set(r.animations)]) console.log('   ', a)
    if (r.readyError) console.log('ready error:', r.readyError)
  }
  await browser.close()
  return recs
}

const normal = await run(false)
const reduced = await run(true)

const allAnims = (recs) => recs.flatMap((r) => r.animations).join('\n')
const checks = {
  'forward nav carries nav-forward type': normal.some((r) => r.types.includes('nav-forward')),
  'back nav carries nav-back type': normal.some((r) => r.types.includes('nav-back')),
  'thumbnail named in old DOM on forward nav': normal.some((r) =>
    r.types.includes('nav-forward') && r.oldNames.some((n) => n.startsWith('product-image ') && n.includes('product-image-leather-backpack'))),
  'hero named in new DOM on forward nav': normal.some((r) =>
    r.types.includes('nav-forward') && r.newNames.some((n) => n.startsWith('product-hero') && n.includes('product-image-leather-backpack'))),
  'morph blur animation runs': /via-blur/.test(allAnims(normal)),
  'directional slide-x runs': /slide-x/.test(allAnims(normal)),
  'suspense reveal slide-up/slide-down present': /slide-up|slide-down/.test(allAnims(normal)),
  'reduced motion: no slide-x': !/slide-x/.test(allAnims(reduced)),
  'reduced motion: no slide-y': !/slide-y/.test(allAnims(reduced)),
  'reduced motion: no via-blur': !/via-blur/.test(allAnims(reduced)),
  'reduced motion: fade-only used': /fade-only/.test(allAnims(reduced)),
}
console.log('\n===== checks =====')
let failed = 0
for (const [k, v] of Object.entries(checks)) {
  console.log(v ? 'PASS' : 'FAIL', k)
  if (!v) failed++
}
process.exit(failed ? 1 : 0)

